test('createInvoice applies gold tier discount (5%) by default', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  assert.equal(result.ok, true);
