  const lines = text.split('\n');

  assert.equal(lines[lines.length - 1], 'Total: €1,675.00');
});

test('renderInvoiceText handles multiple line items', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 2 },
      { sku: 'COPY-HOUR', qty: 3 },
