  invoice = add2.value;
  assert.equal(invoice.lines.length, 3);

  const remove = removeLine(invoice, 'LOGO-PACK');
  assert.equal(remove.ok, true);
  invoice = remove.value;
  assert.equal(invoice.lines.length, 2);
  assert.equal(invoice.lines[0].sku, 'DEV-HOUR');
  assert.equal(invoice.lines[1].sku, 'COPY-HOUR');
});

